#include "stdafx.h"#include "HcdDebugApp.h"#include "FieldsView.h"#include <rsuErr.h>#include <vector>#include <HCD/DynString.h>#include <math.h>#include <macros/en2str.h>using namespace std;// KFieldsViewIMPLEMENT_DYNCREATE(KFieldsView, CListView)KFieldsView::KFieldsView(): m_pCtrl( NULL ){}KFieldsView::~KFieldsView(){}KHcdDebugDoc* KFieldsView::GetDocument(){  ASSERT(m_pDocument->IsKindOf(RUNTIME_CLASS(KHcdDebugDoc)));  return (KHcdDebugDoc*)m_pDocument;}BEGIN_MESSAGE_MAP(KFieldsView, CListView)  ON_MESSAGE( WM_USER, OnWmUser)  ON_WM_TIMER()  ON_NOTIFY_REFLECT(NM_DBLCLK, &KFieldsView::OnNMDblClk)  ON_NOTIFY_REFLECT(LVN_ENDLABELEDIT, &KFieldsView::OnLvnEndlabeledit)END_MESSAGE_MAP()// KFieldsView diagnostics#ifdef _DEBUGvoid KFieldsView::AssertValid() const{  CListView::AssertValid();}#ifndef _WIN32_WCEvoid KFieldsView::Dump(CDumpContext& dc) const{  CListView::Dump(dc);}#endif#endif //_DEBUG// KFieldsView message handlersBOOL KFieldsView::Create(LPCTSTR lpszClassName, LPCTSTR lpszWindowName, DWORD dwStyle, const RECT& rect, CWnd* pParentWnd, UINT nID, CCreateContext* pContext){  dwStyle |= LVS_REPORT | LVS_SINGLESEL | LVS_SHOWSELALWAYS | LVS_ALIGNLEFT | LVS_NOSORTHEADER | LVS_EDITLABELS ;  BOOL r = CListView::Create(lpszClassName, lpszWindowName, dwStyle, rect, pParentWnd, nID, pContext);  m_pCtrl = &GetListCtrl();  m_pCtrl->InsertColumn ( 0, "", LVCFMT_LEFT, rect.right/2, 0 );  m_pCtrl->InsertColumn ( 1, "", LVCFMT_LEFT, rect.right/2-5, 0 );  m_pCtrl->SetExtendedStyle ( LVS_EX_FULLROWSELECT|LVS_EX_GRIDLINES );  SetTimer( 500, 700, NULL );  return r;}LRESULT KFieldsView::OnWmUser( WPARAM wParam, LPARAM lParam ){  if( !(!wParam && 77==lParam) )    return 0L;  KHcdDebugDoc *pDoc = GetDocument();  INotifier* pN = pDoc->GetEventNotifier( eSelectedBlock );  m_connections.push_back( ConnectNotifierA( pN, this, &KFieldsView::OnSelectedBlock ) );  return 1L;}template<size_t _S>int ValueRepresent( char (&buf)[_S], SParamInfo &par ){  buf[0] = 0;  switch( par.evtType )  {  case ehtEnum:    {      tEnum v = *(tEnum*)par.Addr;      if( par.pszEnumVals )      {        tValEnums_ Array;        SplitEnumArgs( par.pszEnumVals, Array );        tValEnums_::iterator it = Array.find( v );        if( Array.end()!=it )        {          LPCSTR pV = it->second.c_str();          if( '_'==*pV )            ++pV;          sprintf_s( buf, "%s", pV );        }        else          sprintf_s( buf, "??? %d", (int)v);      }      else        sprintf_s( buf, "%d", (int)v);    }    break;  case ehtBool:    {      ASSD( !par.pszEnumVals );      tBool v = *(tBool*)par.Addr;      if( 1==v )        strcpy_s( buf, "TRUE");      else if( 0==v )        strcpy_s( buf, "FALSE");      else        sprintf_s( buf, "TRUE (%d)", v);    }    break;  case ehtDynStr:    {      KDynString &psz = *(KDynString*)par.Addr;      if( psz )        strncpy_s( buf, psz, _countof(buf)-1 );    }    break;  case ehtAnalog32:    {      tAnalog32 V = *(tAnalog32*)par.Addr;      if ( V < -1e10 )        V = -1e10;      if ( V > 1e10 )        V = 1e10;      if ( V == 0. )        strcpy_s( buf, "0.0" );      else if ( fabs ( V ) < 1e-5 )        sprintf_s ( buf, "%13.5le", V );      else if ( fabs ( V ) < 1e-4 )        sprintf_s ( buf, "%11.9lf", V );      else if ( fabs ( V ) < 1e-3 )        sprintf_s ( buf, "%10.8lf", V );      else if ( fabs ( V ) < 1e-2 )        sprintf_s ( buf, "%9.7lf", V );      else if ( fabs ( V ) < 1e-1 )        sprintf_s ( buf, "%8.6lf", V );      else if ( fabs ( V ) < 1. )        sprintf_s ( buf, "%7.5lf", V );      else if ( fabs ( V ) < 10. )        sprintf_s ( buf, "%6.4lf", V );      else if ( fabs ( V ) < 100. )        sprintf_s ( buf, "%5.3lf", V );      else if ( fabs ( V ) < 1000. )        sprintf_s ( buf, "%5.2lf", V );      else if ( fabs ( V ) < 10000. )        sprintf_s ( buf, "%5.1lf", V );      else if ( fabs ( V ) > 10000000. )        sprintf_s ( buf, "%e", V );      else if( _isnanf(V) )        strcpy_s( buf, "NaN");      else        sprintf_s ( buf, "%.0lf", V );    }    break;  case ehtDigital32:    sprintf_s( buf, "%d", *(tDigital32*)par.Addr );    break;  }  return 0;}void KFieldsView::OnSelectedBlock( IHcdElement *pBlock ){  m_pCtrl->DeleteAllItems();  m_Vars.clear();  if( !pBlock )    return;  LPCSTR pszName = NULL;  eHcdVType type = ehtHZ;  tHcdVarSizeType_ varSize = 0;  size_t c = pBlock->EnumFields( NULL, 0 );  if( !c )    return;  m_Vars.resize( c );  pBlock->EnumFields( &m_Vars[0], c );  char szName[128];  int added = 0;  for( size_t i=0; i<c; ++i, ++added )  {    SParamInfo &par = m_Vars[i];    szName[0] = 0;    ValueRepresent( szName, par );    added = m_pCtrl->InsertItem( added, szName );    if( par.pszLgxParamName )      sprintf_s( szName, "%s(%s)", par.pszName, par.pszLgxParamName );    else      strcpy_s( szName, par.pszName );    m_pCtrl->SetItemText( added, 1, szName );  }}void SetValue( LPCSTR pszText, SParamInfo &par ){  if( !pszText || !par.Addr )    return;  switch( par.evtType )  {  case ehtDigital32:    *(tDigital32*)par.Addr = atoi(pszText);    break;  case ehtBool:    switch( *pszText )    {    case 't':    case 'T':      *(tBool*)par.Addr = 1;      return;    case 'f':    case 'F':      *(tBool*)par.Addr = 0;      return;    }    *(tBool*)par.Addr = atoi(pszText) ? 1 : 0;    break;  case ehtAnalog32:    *(tAnalog32*)par.Addr = (tAnalog32)atof(pszText);    break;  }}void KFieldsView::OnTimer(UINT_PTR nIDEvent){  if( 500==nIDEvent )  {    KillTimer( nIDEvent );    char value[256];    int n = 0;    for( size_t i=0, c(m_Vars.size()); i<c; ++i, ++n )    {      SParamInfo &par = m_Vars[i];      value[0] = 0;      ValueRepresent( value, par );      m_pCtrl->SetItemText( n, 0, value );    }    SetTimer( 500, 700, NULL );    return;  }  CListView::OnTimer(nIDEvent);}void KFieldsView::OnNMDblClk(NMHDR *pNMHDR, LRESULT *pResult){  // TODO: Add your control notification handler code here  *pResult = 0;  int nItem = m_pCtrl->GetNextItem( -1, LVNI_SELECTED );  if ( nItem < 0 )    return;  if( nItem>=m_Vars.size() )    return;  SParamInfo &par = m_Vars[nItem];  switch( par.evtType )  {  case ehtDigital32:  case ehtAnalog32:  case ehtBool:    break;  default:    return;  }  CEdit *pEd = m_pCtrl->EditLabel( nItem );}void KFieldsView::OnLvnEndlabeledit(NMHDR *pNMHDR, LRESULT *pResult){  NMLVDISPINFO *pDispInfo = reinterpret_cast<NMLVDISPINFO*>(pNMHDR);  *pResult = 0;  if( pDispInfo->item.iItem >= m_Vars.size() )    return;  SParamInfo &par = m_Vars[pDispInfo->item.iItem];  SetValue( pDispInfo->item.pszText, par );}